import{_ as t,o as n,c as a,a2 as i}from"./chunks/framework.BymHWfgO.js";const u=JSON.parse('{"title":"Project Pitch: LLM Serving Inference Scheduler","description":"","frontmatter":{},"headers":[],"relativePath":"00b-project-pitch.md","filePath":"00b-project-pitch.md"}'),r={name:"00b-project-pitch.md"};function o(c,e,s,l,d,h){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="project-pitch-llm-serving-inference-scheduler" tabindex="-1">Project Pitch: LLM Serving Inference Scheduler <a class="header-anchor" href="#project-pitch-llm-serving-inference-scheduler" aria-label="Permalink to &quot;Project Pitch: LLM Serving Inference Scheduler&quot;">​</a></h1><h2 id="_30-second-elevator-pitch" tabindex="-1">30-Second Elevator Pitch <a class="header-anchor" href="#_30-second-elevator-pitch" aria-label="Permalink to &quot;30-Second Elevator Pitch&quot;">​</a></h2><blockquote><p>&quot;I built an iteration-level LLM inference scheduler and control plane inspired by vLLM and Orca. Traditional request-level batching causes severe GPU underutilization because short requests must wait for long requests to finish generating tokens. My scheduler implements continuous batching, dynamically inserting new prompts at each forward pass, and pairs it with a paged KV-cache memory allocator that treats GPU memory like virtual memory pages. This cuts KV memory fragmentation by over 90% and delivers high-throughput token streaming with low time-to-first-token.&quot;</p></blockquote><hr><h2 id="_2-minute-technical-interview-pitch" tabindex="-1">2-Minute Technical Interview Pitch <a class="header-anchor" href="#_2-minute-technical-interview-pitch" aria-label="Permalink to &quot;2-Minute Technical Interview Pitch&quot;">​</a></h2><blockquote><p>&quot;Serving Large Language Models in production presents two critical systems challenges: memory fragmentation in the Key-Value (KV) cache and severe GPU compute starvation under dynamic sequence lengths.</p><p>In naive static batching, requests of varying lengths are padded together. The GPU remains locked until the longest request completes, wasting over 60% of GPU compute and leaving memory unusable.</p><p>To solve this, I designed and built <strong>15-LLM-Inference-Scheduler</strong>, a continuous-batching serving engine and multi-worker control plane.</p><p>First, I implemented iteration-level continuous batching in <code>backend/src/batching/continuous.py</code>. Rather than waiting for a whole batch to finish, the scheduler executes a single autoregressive decoding step for active sequences, evicts completed sequences immediately, and injects newly arrived prompts into the very next iteration.</p><p>Second, to manage the explosive memory demands of self-attention, I implemented a Paged KV-Cache allocator in <code>backend/src/kv/paged.py</code>. Modeled directly after OS virtual memory paging, physical KV cache memory is sliced into small fixed-size blocks (16 tokens each). Logical request tokens map to physical blocks through a page table, completely eliminating external memory fragmentation and allowing multiple concurrent sequences to share prefill prefixes.</p><p>Third, I decoupled compute-heavy prompt prefill from memory-bandwidth-bound token decoding using a chunked prefill scheduler, maintaining smooth inter-token latency (ITL) under heavy prompt arrival bursts.</p><p>The control plane exposes standard REST and Server-Sent Events (SSE) streaming APIs in FastAPI, routed to a pool of GPU worker replicas with health tracking. The frontend is built in React and TypeScript, visualizing active queue states and latency percentiles. The backend is validated by 99 automated pytest tests covering admission rejection, prefill preemption, and memory page reclamation.&quot;</p></blockquote>',6)])])}const m=t(r,[["render",o]]);export{u as __pageData,m as default};
